WITH kept_keys AS (SELECT id FROM payments EXCEPT ALL SELECT id FROM payments WHERE status = 'FAILED'), verified AS (SELECT s.* FROM payments s INNER JOIN kept_keys k ON s.id = k.id), with_windows AS (SELECT *, AVG(amount) OVER (PARTITION BY status, method ORDER BY CAST(paid_at AS BIGINT) ASC RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS amount_avg_90d FROM verified WHERE method = 'bank_transfer'), filtered AS (SELECT id, order_id, amount, paid_at, status, amount_avg_90d, DATE_FORMAT(paid_at, 'yyyy-MM-dd') AS paid_at_label, COALESCE(method, 'UNKNOWN') AS resolved_method FROM with_windows WHERE amount_avg_90d = 1136), cleaned AS (SELECT *, INITCAP(TRIM(status)) AS status_title FROM filtered WHERE paid_at >= DATE '2023-05-31' AND order_id IS NOT NULL), enriched AS (SELECT id, amount, paid_at, amount_avg_90d, resolved_method, ROUND(amount / SUM(amount) OVER (PARTITION BY MONTH(paid_at), order_id), 4) AS amount_share, AVG(amount_avg_90d) OVER w_recent AS amount_avg_90d_avg_7d, CUME_DIST() OVER (ORDER BY amount DESC NULLS FIRST) AS amount_cume_dist FROM cleaned WINDOW w_recent AS (PARTITION BY order_id, status ORDER BY CAST(paid_at AS BIGINT) ASC RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW)) SELECT id, paid_at, amount_avg_90d, resolved_method, amount_share, amount_avg_90d_avg_7d, amount_cume_dist FROM enriched ORDER BY paid_at DESC, amount_cume_dist ASC
